import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused Subtract+HardSwish kernel
sub_hswish_src = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void sub_hswish_kernel(const float* input, float* output, int numel, float sub_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        float x = input[idx] - sub_val;
        float relu = fminf(fmaxf(x + 3.0f, 0.0f), 6.0f);
        output[idx] = x * relu / 6.0f;
    }
}

torch::Tensor sub_hswish_cuda(torch::Tensor input, float sub_val) {
    auto output = torch::empty_like(input);
    int numel = input.numel();
    int threads = 256;
    int blocks = (numel + threads - 1) / threads;
    sub_hswish_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), numel, sub_val);
    return output;
}
"""

# Custom fused MaxPool2D+Mish kernel
pool_mish_src = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void pool_mish_kernel(const float* input, float* output,
                                int B, int C, int H, int W,
                                int K, int OH, int OW) {
    int n = blockIdx.x;
    int c = blockIdx.y;
    int oh = blockIdx.z / OW;
    int ow = blockIdx.z % OW;

    float max_val = -INFINITY;
    for(int kh=0; kh<K; ++kh) {
        for(int kw=0; kw<K; ++kw) {
            int h = oh*K + kh;
            int w = ow*K + kw;
            if(h < H && w < W) {
                float val = input[n*C*H*W + c*H*W + h*W + w];
                max_val = fmaxf(max_val, val);
            }
        }
    }

    // Mish activation
    float sp = log1pf(expf(max_val));
    float mish = max_val * tanhf(sp);
    output[n*C*OH*OW + c*OH*OW + oh*OW + ow] = mish;
}

torch::Tensor pool_mish_cuda(torch::Tensor input, int K) {
    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int OH = H / K;
    int OW = W / K;

    auto output = torch::empty({B, C, OH, OW}, input.options());
    dim3 grid(B, C, OH*OW);
    pool_mish_kernel<<<grid, 1>>>(input.data_ptr<float>(), output.data_ptr<float>(),
                                 B, C, H, W, K, OH, OW);
    return output;
}
"""

# Load CUDA extensions
sub_hswish = load_inline(
    name='sub_hswish',
    cpp_sources="torch::Tensor sub_hswish_cuda(torch::Tensor input, float sub_val);",
    cuda_sources=sub_hswish_src,
    functions=['sub_hswish_cuda'],
    verbose=False
)

pool_mish = load_inline(
    name='pool_mish',
    cpp_sources="torch::Tensor pool_mish_cuda(torch::Tensor input, int K);",
    cuda_sources=pool_mish_src,
    functions=['pool_mish_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, subtract_value, pool_kernel_size):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.sub_val = subtract_value
        self.pool_size = pool_kernel_size

    def forward(self, x):
        x = self.conv(x)
        x = sub_hswish.sub_hswish_cuda(x, self.sub_val)
        x = pool_mish.pool_mish_cuda(x, self.pool_size)
        return x
